#!/usr/bin/env node
// Regenerate profile/hooks.json with this checkout's absolute probe-hook path.
// The committed hooks.json is generated by this script; Codex runs hook
// commands with the session cwd, so an absolute interpreter path is required.
import { writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const hook = join(here, "probe-hook.mjs").replaceAll("\\", "/");
const command = `node "${hook}"`;

const group = (extra = {}) => [{ hooks: [{ type: "command", command, timeout: 30, ...extra }] }];
const hooks = {
  description:
    "S1 throwaway probe hooks. Logs every documented lifecycle payload; never decides or blocks.",
  hooks: {
    SessionStart: group(),
    PermissionRequest: group(),
    UserPromptSubmit: group(),
    Stop: group(),
    SubagentStart: group(),
    SubagentStop: group(),
    Interrupt: group({ timeout: 3 }),
    SessionEnd: group({ timeout: 3 }),
  },
};

writeFileSync(join(here, "profile", "hooks.json"), JSON.stringify(hooks, null, 2) + "\n");
console.log(`wrote profile/hooks.json -> ${command}`);
